'use strict';
const fs = require('node:fs');
const assert = require('node:assert/strict');
const Ajv = require('ajv/dist/2020');
const { read, bytes } = require('./lib/epic-f-consumer');
const { collectScannedFiles, stripComments, validateRenderedText } = require('./validate-brand-claims');
const { buildCleanup } = require('./build-epic-f-content-cleanup');

function scanProductSource(file, text) {
  const source = stripComments(text);
  const errors = [];
  if (/\b(?:product|card_product|item|result)(?:\.product)?(?:\.description(?:Html)?|\[['"]description['"]\])/.test(source) && file !== 'snippets/rhino-product-description.liquid') errors.push('Raw Product description bypass in ' + file);
  if (/\bproduct\s*\|\s*structured_data/.test(source) && file !== 'snippets/rhino-product-structured-data.liquid') errors.push('Native Product JSON-LD bypass in ' + file);
  if (/metafields(?:\.rhino|\[['"]rhino['"]\])/.test(source)) errors.push('F1 has no authorized technical metafield renderer: ' + file);
  if (/(?:product|card_product)\.(?:title|tags|collections|handle|vendor|type)\s*(?:contains|==)\s*['"](?:machine|machines|TrimMaster)/i.test(source)) errors.push('Classification fallback in ' + file);
  if (/tests\/fixtures|epic-f-consumer\.json/.test(source) && /^(?:layout|sections|snippets|templates|config)\//.test(file)) errors.push('Fixture import into theme: ' + file);
  return errors;
}
function run() {
  const errors = [];
  for (const absolute of collectScannedFiles()) {
    const file = require('node:path').relative(process.cwd(), absolute).replaceAll('\\', '/');
    errors.push(...scanProductSource(file, fs.readFileSync(absolute, 'utf8')));
  }
  const artifact = read('data/epic-f-content-cleanup-plan.json');
  const ajv = new Ajv();
  assert(ajv.validate(read('schemas/epic-f-content-cleanup-plan.schema.json'), artifact), JSON.stringify(ajv.errors));
  assert.equal(bytes(artifact), bytes(buildCleanup()), 'Cleanup plan/source drift');
  const fixture = read('tests/fixtures/epic-f-consumer.json');
  for (const text of fixture.customerNarratives) errors.push(...validateRenderedText('future-machine-narrative', text));
  assert.deepEqual(errors, []);
  console.log(`F1 Product source contract valid; ${artifact.rows.length} exact Products in unexecuted cleanup scope. Historical source claims remain unresolved.`);
}
if (require.main === module) run();
module.exports = { scanProductSource, run };

'use strict';

const fs = require('node:fs');
const Ajv = require('ajv/dist/2020');

const contract = require('../data/epic-f-support-resources-contract.json');
const contractSchema = require('../schemas/epic-f-support-resources-contract.schema.json');
const batch3b = require('../data/epic-e-batch-3b-contracts.json');
const batch3bDecisions = require('../data/epic-e-batch-3b-decision-packet.json');
const batch3cDecisions = require('../data/epic-e-batch-3c-decision-packet.json');
const resourceCatalog = require('../data/epic-e-resource-catalog.json');
const { contracts: batch3c } = require('./lib/epic-e-batch-3c-contract');
const packetSchema = require('../schemas/epic-f-support-resources.schema.json');
const projectionSchema = require('../schemas/epic-f-support-resources-projection.schema.json');

const errors = [];

function fail(message) {
    errors.push(message);
}

function sameMembers(actual, expected) {
    return (
        Array.isArray(actual) &&
        Array.isArray(expected) &&
        actual.length === expected.length &&
        [...actual].sort().every((value, index) => value === [...expected].sort()[index])
    );
}

const ajv = new Ajv({
    strict: false,
    allErrors: true
});

const validateContract = ajv.compile(contractSchema);
const validatePacketSchema = ajv.compile(packetSchema);
const validateProjectionSchema = ajv.compile(projectionSchema);

if (
    typeof validatePacketSchema !== 'function' ||
    typeof validateProjectionSchema !== 'function'
) {
    fail('F6 packet/projection schemas did not compile');
}

if (!validateContract(contract)) {
    for (const error of validateContract.errors || []) {
        fail(
            `Contract schema ${error.instancePath || '/'} ${error.message || 'is invalid'}`
        );
    }
}

/*
 * Upstream files are architectural authorities
 * F6 consumes them; it does not redefine their semantics.
 */
for (const path of Object.values(contract.upstream)) {
    if (!fs.existsSync(path)) {
        fail(`Missing upstream F6 authority: ${path}`);
    }
}

/*
 * Warranty / service ownership
 */
const warrantyDecision = batch3cDecisions.decisions.find(
    decision => decision.id === contract.warranty.decisionId
);

if (!warrantyDecision) {
    fail(`Missing upstream decision ${contract.warranty.decisionId}`);
} else {
    if (warrantyDecision.pbi !== contract.warranty.sourcePbi) {
        fail(
            `${contract.warranty.decisionId} must remain owned by ${contract.warranty.sourcePbi}`
        );
    }

    if (
        warrantyDecision.decisionState !==
        contract.warranty.currentExpectedDecisionState
    ) {
        fail(
            `${contract.warranty.decisionId} upstream state changed from ` +
            `${contract.warranty.currentExpectedDecisionState} to ` +
            `${warrantyDecision.decisionState}; review F-PBI-010B before changing F6`
        );
    }

    if (
        warrantyDecision.decisionState !== 'approved' &&
        warrantyDecision.approvalDecisionId !== null
    ) {
        fail(
            `${contract.warranty.decisionId} has an approval ID without an approved state`
        );
    }
}

if (!sameMembers(contract.warranty.roles, batch3c.warranty.roles)) {
    fail(
        'F6 warranty roles must exactly match the Epic E warranty role contract'
    );
}

if (
    batch3c.warranty.storageDecision !==
    'No new Shopify warranty definition or metaobject. Reusable current terms and entity ownership are not approved. Repository typed policy/class/mapping references support review; approved resource delivery reuses E-PBI-018B.'
) {
    fail(
        'Epic E warranty storage decision has changed; review F6 before proceeding'
    );
}

if (
    contract.warranty.newShopifyDefinitionAllowed !== false ||
    contract.warranty.newWarrantyMetaobjectAllowed !== false
) {
    fail('F6 must not create a Shopify warranty definition or metaobject');
}

if (contract.warranty.neutralContactRoute !== '/pages/contact') {
    fail('F6 neutral Contact route must remain /pages/contact');
}

if (contract.warranty.warrantyDestinationFallbackAllowed !== false) {
    fail('Neutral Contact must not become a warranty destination fallback');
}

/*
 * Resource governance
 */
const resourceDecision = batch3bDecisions.decisions.find(
    decision => decision.id === contract.resources.decisionId
);

if (!resourceDecision) {
    fail(`Missing upstream decision ${contract.resources.decisionId}`);
} else {
    if (
        resourceDecision.state !==
        contract.resources.currentExpectedDecisionState
    ) {
        fail(
            `${contract.resources.decisionId} upstream state changed from ` +
            `${contract.resources.currentExpectedDecisionState} to ` +
            `${resourceDecision.state}; review F-PBI-011B before changing F6`
        );
    }

    if (
        resourceDecision.state !== 'approved' &&
        resourceDecision.approval !== null
    ) {
        fail(
            `${contract.resources.decisionId} has approval evidence without an approved state`
        );
    }
}

if (!sameMembers(contract.resources.types, batch3b.resources.types)) {
    fail('F6 resource types must exactly match Epic E');
}

if (!sameMembers(contract.resources.states, batch3b.resources.states)) {
    fail('F6 resource lifecycle states must exactly match Epic E');
}

if (!sameMembers(contract.resources.visibility, batch3b.resources.visibility)) {
    fail('F6 resource visibility states must exactly match Epic E');
}

const expectedFields = {
    manual: 'manual_files',
    diagram: 'diagram_files',
    instruction: 'instruction_files',
    video: 'video_files',
    support: 'support_files'
};

for (const [type, key] of Object.entries(expectedFields)) {
    if (contract.resources.resourceFields[type] !== key) {
        fail(`F6 resource field for ${type} must be ${key}`);
    }

    const upstreamField = batch3b.fields.find(field => field.key === key);

    if (!upstreamField) {
        fail(`Missing Epic E resource field ${key}`);
        continue;
    }

    if (
        upstreamField.sourcePbi !== 'E-PBI-018B' ||
        upstreamField.type !== 'list.file_reference' ||
        upstreamField.ownerType !== 'PRODUCT' ||
        upstreamField.definitionDecisionState !== 'approved' ||
        upstreamField.valueApprovalRequired !== true
    ) {
        fail(`Epic E resource field ${key} no longer matches the F6 contract`);
    }
}

if (contract.resources.supportFieldCustomerVisible !== false) {
    fail('support_files must remain customer-ineligible');
}

/*
 * Current catalog safety.
 *
 * Candidate evidence is allowed to exist, but nothing currently present may be
 * treated as a customer grant merely because it has a File GID or reachable
 * binary.
 */
for (const resource of resourceCatalog.resources || []) {
    if (resource.visibility === 'support_only' || resource.visibility === 'internal') {
        if (
            resource.sourceRole !== 'evidence_only' &&
            resource.resourceType === 'support'
        ) {
            fail(
                `Restricted support resource ${resource.resourceId} unexpectedly has ` +
                `sourceRol ${resource.sourceRole}`
            );
        }
    }

    if (resource.status !== 'current' && resource.canonical === true) {
        fail(`Non-current resource ${resource.resourceId} must not be canonical`);
    }

    if (
        resource.visibility !== 'customer' &&
        resource.publicationApproved === true
    ) {
        fail(`Non-customer resource ${resource.resourceId} must not be publication-approved`);
    }
}

/*
 * F-PBI-010A / 011A repository boundary.
 */
if (contract.runtimeActivation !== false) {
    fail('F6 runtime activation must remain disabled in A scope');
}

if (
    contract.release.realWarrantyGrantCount !== 0 ||
    contract.release.realResourceGrantCount !== 0
) {
    fail('F6 A scope must begin with zero real warranty/resource grants');
}

if (
    contract.release.adminMutationAuthorized ||
    contract.release.productMutationAuthorized ||
    contract.release.fileMutationAuthorized ||
    contract.release.pageMutationAuthorized ||
    contract.release.themePushAuthorized
) {
    fail('F6 A scope cannot authorize live mutation or theme push');
}

// Architecture enforcement supplements (and does not replace) the manual checkpoint.
const crypto = require('node:crypto');
const consumer = require('./lib/epic-f-consumer');
for (const [path, hash] of Object.entries(require('../tests/fixtures/epic-f-support-resources-baseline.json'))) {
    const liveMedia = require('./lib/epic-f-live-media-activation');
    const exactDevelopmentMedia = path === liveMedia.FILE && liveMedia.historicalSourceMatches(path, hash);
    if (crypto.createHash('sha256').update(fs.readFileSync(path)).digest('hex') !== hash && !exactDevelopmentMedia) fail('F6 changed preserved surface: ' + path);
}
if (require('../data/epic-f-consumer-release.json').grants.length !== 0) fail('Unexpected real grants: stop; activation is not authorized');
if (fs.readFileSync('snippets/rhino-product-support-resources-projection.liquid', 'utf8').replaceAll('\r\n', '\n') !== consumer.buildSupportResourcesProjection()) fail('F6 generated projection is stale');
const main = fs.readFileSync('sections/main-product.liquid', 'utf8');
if ((main.match(/render 'rhino-product-support-resources-projection'/g) || []).length !== 1) fail('F6 must integrate exactly once');
if (!/if rhino_consumer_route == 'machine'[\s\S]*?rhino-product-fact-projection[\s\S]*?rhino-product-context-delivery-projection[\s\S]*?rhino-product-support-resources-projection/.test(main)) fail('F6 must follow existing machine-only projections');
for (const name of ['support', 'resources']) {
    const text = fs.readFileSync('snippets/rhino-machine-' + name + '.liquid', 'utf8');
    if (!text.includes("request.host == 'machine.local' and projection.fixture_only")) fail('F6 fixture rendering must remain isolated');
    if (/product\.(?:description|metafields|vendor|tags)|shop\.|support_files|<script|all_products|autoplay[=\s]/.test(text)) fail('Forbidden F6 authority/controller: ' + name);
}
const resources = fs.readFileSync('snippets/rhino-machine-resources.liquid', 'utf8');
if (!/<deferred-media[\s\S]*?<template>\s*<iframe[\s\S]*?<\/template>/.test(resources)) fail('Use native deferred video and inert template');
if (projectionSchema.$defs.resourceProjection.properties.type.enum.includes('support')) fail('support_files must be structurally customer-ineligible');

if (errors.length) {
    console.error('Epic F support/resources validation failed:');
    for (const error of errors) {
        console.error(`- ${error}`);
    }
    process.exitCode = 1;
} else {
    console.log(
        'Epic F support/resources contract validation passed. ' +
        'F-PBI-010A/011A architecture only; live grants remain zero.'
    );
}

'use strict';

// Pure repository aggregation: no Shopify client, network adapter or event emitter.
const fs = require('node:fs');
const { execFileSync } = require('node:child_process');
const { read, fileHash, canonical, schemaErrors } = require('./epic-f-governance');
const { historicalHashMatches, approvedNewSnippet } = require('./epic-f-release-cleanup-binding');
const contractPath = 'data/epic-f-machine-page-readiness-contract.json';
const packetPath = 'data/epic-f-machine-page-readiness.json';
const inventoryPath = 'docs/project/epic-f-machine-inventory.json';
const planPath = 'data/epic-f-machine-template-rollout-plan.json';
const policyPath = 'data/epic-f-machine-template-rollout-policy.json';
const consumerPath = 'data/epic-f-consumer-release.json';
const mediaPath = 'data/epic-f-media-release.json';
const evidencePath = n => `docs/qa/evidence/epic-f/batch-f${n}-validation.json`;
const performancePath = n => `docs/qa/evidence/epic-f/batch-f${n}-performance-runtime.json`;
const unique = values => [...new Set(values)];
const machineGids = ['8905779937477', '8905780756677', '8905781248197', '8905781412037', '8905781477573', '8905784131781', '8905784197317', '8905784262853', '8905784328389', '8905785344197', '8905785868485'].map(id => `gid://shopify/Product/${id}`);

function sources() {
    const c = read(contractPath);
    const paths = unique([contractPath, ...Object.keys(c.sourcePins),
        ...read(consumerPath).provenance.map(p => p.path),
        'docs/project/implementation-records/f-pbi-001-005-batch-f1.md',
        'docs/project/implementation-records/f-pbi-016-017a-batch-f7.md',
        ...Array.from({ length: 7 }, (_, i) => `docs/project/epic-f-batch-f${i + 1}-file-manifest.json`),
        'tests/fixtures/epic-f-f8-file-baseline.json']);
    return paths.sort().map(path => {
        let d = {};
        if (path.endsWith('.json')) d = read(path);
        return { path, sha256: fileHash(path), sourceObservedAt: d.capturedAt || d.observedAt || d.assessedAt || d.asOf || d.preparedAt || null,
            observationKind: path.includes('admin-snapshot') || path.includes('machine-admin-read') ? 'historical_admin' : 'repository_artifact' };
    });
}

function grantCounts() {
    const consumer = read(consumerPath), media = read(mediaPath);
    // No live grant shape is supported by the F1-F7 release schema. Report any
    // unexpected row exactly and fail, even if its domain is unrecognizable.
    const groups = {
        specifications: ['electrical', 'motor_speed', 'tool_mount', 'water_fluid', 'durable_measurements', 'crate_measurements'],
        contents: ['included_components', 'optional_components'],
        contextual: ['compatibility', 'recommendations'],
        delivery: ['fulfillment_class', 'pickup_region', 'availability_authority'],
        warranty: ['warranty_support'], manuals: ['customer_manuals'],
        diagrams_instructions: ['diagrams_instructions_videos'], videos: ['diagrams_instructions_videos'],
        support_files: ['support_files']
    };
    const rows = [{ domain: 'media', before: read('tests/fixtures/epic-f-f8-governance-baseline.json').mediaGrantsBefore,
        current: media.grants.length, source: mediaPath }];
    for (const [domain, domains] of Object.entries(groups)) rows.push({ domain, before: 0,
        current: consumer.grants.filter(g => domains.includes(g.domain)).length, source: consumerPath });
    const approvedMedia = require('./epic-f-live-media-activation').authorizedCount();
    return { counts: rows, consumerTotalBefore: read('tests/fixtures/epic-f-f8-governance-baseline.json').consumerGrantsBefore,
        consumerTotalCurrent: consumer.grants.length,
        unexpectedGrants: [...consumer.grants.map(grant => ({ source: consumerPath, domain: grant.domain || 'unknown', grant })),
            ...(approvedMedia===media.grants.length?[]:media.grants.map(grant => ({ source: mediaPath, domain: 'media', grant })))],
        scope: 'Actual repository release artifacts; exact bound development media grants recognized; fixtures excluded; final launch rights and certification remain unapproved' };
}

function build(assessedAt) {
    if (!Number.isFinite(Date.parse(assessedAt))) throw new Error('Valid assessment timestamp required');
    const c = read(contractPath), inventory = read(inventoryPath), plan = read(planPath), policy = read(policyPath);
    const downstream = read('data/epic-e-downstream-readiness.json').rows.filter(r => r.consumer === 'F');
    const batches = Array.from({ length: 7 }, (_, i) => ({ batch: `F${i + 1}`, path: evidencePath(i + 1), ...read(evidencePath(i + 1)) }));
    const before = read('tests/fixtures/epic-f-machine-template-before.json');
    const handoff = read('data/epic-e-deferred-decision-handoff.json');
    const domainMatrix = c.domains.map(domain => {
        const upstream = downstream.filter(r => domain.epicEDomains.includes(r.domain));
        const blocked = domain.governedFact || ['payment_decision', 'measurement_instrumentation', 'rollout_execution'].includes(domain.id);
        return { id: domain.id, owningPbis: domain.owningPbis, governedFact: domain.governedFact,
            implementation: domain.implementation, valueState: blocked ? 'blocked' : 'not_applicable',
            adminEvidence: ['measurement_contract', 'measurement_instrumentation', 'rollout_plan'].includes(domain.id) ? 'not_applicable' : 'stale',
            migrationReconciliation: domain.governedFact || domain.id === 'rollout_execution' ? 'blocked' : 'not_applicable',
            activationAuthorization: blocked ? 'not_granted' : 'not_applicable',
            customerPresentation: domain.governedFact ? 'suppressed' : 'not_applicable',
            shopifyParity: ['measurement_contract', 'rollout_plan'].includes(domain.id) ? 'not_applicable' : 'unverified',
            releaseCertification: domain.id === 'performance' ? 'deferred' : 'blocked',
            decisionIds: unique([...domain.decisionIds, ...upstream.flatMap(r => r.blockedDecisionIds)]),
            upstreamDomains: domain.epicEDomains, upstreamPlans: upstream.map(r => r.planId),
            evidenceReferences: [contractPath, ...batches.map(b => b.path), ...(upstream.length ? ['data/epic-e-downstream-readiness.json'] : [])],
            presentationScope: c.presentationScope,
            note: domain.governedFact ? 'Renderer complete; no eligible activated customer facts; safe suppression is not fact readiness' :
                domain.id === 'native_purchase' ? 'Native Product/Variant purchase, payment terms and pickup retained; no F factual grant; local fixtures only' :
                domain.id === 'contact' ? 'Neutral route/context adapter implemented; actual Shopify integration and inquiry submission unverified' : 'Repository evidence only; live release remains gated' };
    });
    const factual = domainMatrix.filter(d => d.governedFact);
    const machines = machineGids.map(productGid => {
        const product = inventory.products.find(p => p.productGid === productGid);
        const assessment = plan.assessments.find(p => p.productGid === productGid);
        if (!product || !assessment) throw new Error(`Missing governed machine ${productGid}`);
        return { productGid, displayLabel: product.title, governedClass: product.classification.value,
            classification: { sourceValueState: product.classification.state, decisionId: product.classification.decisionId,
                source: product.classification.source, liveValue: null, migrationReconciliation: 'blocked' },
            evidence: { historicalObservedAt: product.currentObservationAt, currentAdminEvidence: 'stale', currentLiveState: null },
            rolloutAssessment: { historicalEligibility: assessment.eligibility, conditionalFutureCandidate: assessment.futureCandidate,
                currentEligible: false, executable: false, source: planPath },
            template: { historicalSuffix: assessment.observedTemplateSuffix, historicalObservedAt: before.observedAt,
                evidenceState: 'stale', currentSuffix: null, intendedSuffix: policy.intendedSuffix, assignmentPerformed: false },
            historicalProductState: { status: assessment.status, publication: assessment.publication },
            modules: factual.map(d => ({ domain: d.id, implementation: d.implementation, valueState: d.valueState,
                eligibleFactValue: null, adminEvidence: d.adminEvidence, migrationReconciliation: d.migrationReconciliation,
                activationAuthorization: d.activationAuthorization, customerPresentation: d.customerPresentation,
                shopifyParity: d.shopifyParity, releaseCertification: d.releaseCertification, decisionIds: d.decisionIds })),
            customerPresentation: { repositoryGovernedModules: 'suppressed', actualShopifyPresentation: 'unverified' },
            blockers: unique([...product.blockers, ...assessment.reasons, ...factual.flatMap(d => d.decisionIds)]) };
    });
    const snapshots = [
        { path: 'docs/qa/evidence/epic-e/2026-09-03-epic-e-admin-snapshot.json', observedAt: read('data/epic-e-admin-readiness.json').snapshotCapturedAt,
            expiresAt: read(consumerPath).factEligibilityExpiresAt, freshnessRule: 'Epic E maximumAgeDaysForMutationPlanning=7', coverage: 'Historical Epic E dataset snapshot' },
        { path: before.sourcePath, observedAt: before.observedAt,
            expiresAt: new Date(Date.parse(before.observedAt) + policy.beforeRead.maxAgeSeconds * 1000).toISOString(),
            freshnessRule: `F7 before-read maximum age ${policy.beforeRead.maxAgeSeconds} seconds; historical incomplete read never authorizes execution`,
            coverage: '11 exact machines; incomplete protected-field/theme/publication execution coverage' }
    ].map(s => ({ ...s, state: 'stale' }));
    const performance = Array.from({ length: 4 }, (_, i) => {
        const path = performancePath(i + 3), d = read(path);
        return { batch: `F${i + 3}`, path, observedAt: d.assessedAt, exitCode: d.exitCode, scope: d.scope,
            thresholdChanges: d.thresholdChanges ?? null, budgets: d.budgets,
            observations: d.results.map(r => ({ state: r.state, profile: r.profile, violations: r.violations,
                expected: r.expected || 'pass', expectedResult: r.expectedResult ?? (r.violations.length === 0),
                requestedRuns: r.record.requestedRuns, timestamps: r.record.samples.map(s => s.timestamp),
                fixtureOnly: r.record.samples.every(s => s.fixtureOnly), stage: r.record.stage })) };
    });
    const coverage = [
        ['shell', 2, [320, 360, 390, 768, 1024, 1440, 1920], true],
        ['gallery', 3, [320, 390, 768, 1440], false],
        ['specifications_contents', 4, [320, 390, 768, 1440], true],
        ['contextual_delivery', 5, [320, 390, 768, 1440], true],
        ['support_resources', 6, [320, 390, 768, 1440], true]
    ].map(([domain, batch, widths, enlarged]) => ({ domain, widths, source: evidencePath(batch),
        textEnlargement: enlarged ? '200% root-font simulation' : 'Inherited F2 shell; gallery viewport/modal coverage',
        actualChromiumZoom: enlarged ? '200%; chrome.tabs.setZoom(2), layout viewport and DPR verified' : 'Inherited F2 shell zoom; separate gallery zoom inspection',
        keyboardFocus: 'passed in local tested states', axeSeriousCriticalFindings: 0, scope: 'local fixtures; global chrome/provider/live parity outside certification' }));
    const diagnostics = read('docs/qa/evidence/epic-f/batch-f8-historical-diagnostics.json');
    const f7 = read(evidencePath(7));
    const status = { 'F-PBI-018': 'partial', 'F-PBI-018A': 'complete_repository_scope', 'F-PBI-018B': 'open_not_ready',
        'F-PBI-013': 'open', 'F-DEC-001': 'open', 'F-PBI-014B': 'open_partial', 'F-PBI-015B': 'deferred',
        'F-PBI-016': 'contract_complete_instrumentation_blocked', 'F-PBI-017A': 'complete_repository_scope', 'F-PBI-017B': 'open_blocked_not_authorized' };
    for (const n of ['004', '006', '007', '008', '009', '010', '011']) status[`F-PBI-${n}B`] = 'open_not_ready';
    const packet = { $schema: '../schemas/epic-f-machine-page-readiness.schema.json', schemaVersion: 1,
        assessedAt, scope: c.scope, repositoryRevision: execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim(),
        repositoryRevisionScope: 'HEAD plus source-bound uncommitted F1-F8 working tree; hashes are authority',
        evidenceProvenance: sources(), repositoryAggregatePassed: false, liveReleaseState: 'not_ready_not_authorized',
        machines, domainMatrix, realGrants: grantCounts(),
        adminEvidence: { state: 'stale', assessedAt, snapshots, currentAudit: null,
            dependentDomains: domainMatrix.filter(d => d.adminEvidence === 'stale').map(d => d.id),
            note: 'Generation time does not refresh source observation time; no current audit run' },
        epicE: { migrationReconciliation: 'blocked', currentReconciliation: 'unverified',
            downstreamAsOf: read('data/epic-e-downstream-readiness.json').asOf, downstreamRows: downstream,
            deferredDecisions: handoff.decisions.map(d => ({ decisionId: d.decisionId, sourceDecisionIds: d.sourceDecisionIds,
                currentState: d.currentState, sourceState: d.sourceState, domains: d.domains })),
            inheritedDecisions: [{ decisionId: 'B3C-D03', state: 'blocked' }, { decisionId: 'B3B-D06', state: 'pending' }],
